import type { JsonSchema } from "../casing/schemaKeyCasing";
import type { Overlay } from "../overlay/overlay";
import { emitFixtureType } from "./emitType";

const GENERATED_HEADER = `// Generated by @autumn/atmn-generator from packages/openapi/openapi-internal.yml.
// Do not edit — run \`bun generate\` in packages/atmn-generator instead.
`;

/**
 * Builders are typed identity functions. They exist for three reasons and none
 * of them is transformation: autocomplete while writing a fixture, a findable
 * call for ast-grep to replace on pull, and a name the static-fixtures lint can
 * anchor to. Casing is handled once by the mapper, not per builder.
 */
export const emitFeaturesModule = ({
	schema,
	overlay,
}: {
	schema: JsonSchema;
	overlay: Overlay;
}): string =>
	[
		GENERATED_HEADER,
		emitFixtureType({
			name: "Feature",
			schema,
			collection: "features",
			overlay,
		}),
		`export const feature = (input: Feature): Feature => input;\n`,
	].join("\n");
